+    if (filename == "deposit.html" || filename == "withdraw.html") {
+        replacements.push_back({"{{accounts}}",
+                                format_account_options(service, username)});
+    }
+    return write_template(conn, HttpStatus::OK, filename, replacements);
+}
+
+Result<void> handle_register(Connection& conn, BankService& service,
+                             const QueryFields& form) {
+    std::string username = field(form, "username");
+    std::string password = field(form, "password");
+    std::string confirm = field(form, "confirm_password");
+    if (username.empty() || password.empty()) {
+        return render_error(conn, HttpStatus::BadRequest,
+                            "username and password are required");
+    }
+    if (!confirm.empty() && confirm != password) {
+        return render_error(conn, HttpStatus::BadRequest,
+                            "password confirmation does not match");
+    }
+    if (!service.registerUser(username, password)) {
+        return render_error(conn, HttpStatus::BadRequest,
+                            "user already exists or username is invalid");
+    }
+    save_data(service);
+    return render_home(conn, service, "register success", username);
+}
+
+Result<void> handle_login(Connection& conn, BankService& service,
+                          const QueryFields& form) {
+    std::string username = field(form, "username");
+    if (service.login(username, field(form, "password"))) {
+        return render_home(conn, service, "login success", username);
+    }
+    return render_error(conn, HttpStatus::BadRequest, "invalid username or password");
+}
+
+Result<void> handle_savings(Connection& conn, BankService& service,
+                            const QueryFields& form) {
+    std::string username = field(form, "username");
+    std::string account_id = field(form, "account_id");
+    double rate = 0;
+    if (username.empty() || account_id.empty() || !parse_double(form, "rate", rate)) {
+        return render_error(conn, HttpStatus::BadRequest,
+                            "username, account_id, and rate are required");
+    }
+    if (service.createSavingsAccount(username, account_id, rate) == nullptr) {
+        return render_error(conn, HttpStatus::BadRequest,
+                            "cannot create savings account");
+    }
+    save_data(service);
+    return render_simple_page(conn, service, "account.html", "savings account created",
+                              username);
+}
+
+Result<void> handle_credit(Connection& conn, BankService& service,
+                           const QueryFields& form) {
+    std::string username = field(form, "username");
+    std::string account_id = field(form, "account_id");
+    double credit = 0;
+    double rate = 0;
+    double fee = 0;
+    if (username.empty() || account_id.empty() ||
+        !parse_double(form, "credit", credit) ||
+        !parse_double(form, "rate", rate) || !parse_double(form, "fee", fee)) {
+        return render_error(conn, HttpStatus::BadRequest,
+                            "username, account_id, credit, rate, and fee are required");
+    }
+    if (service.createCreditAccount(username, account_id, credit, rate, fee) ==
+        nullptr) {
+        return render_error(conn, HttpStatus::BadRequest,
+                            "cannot create credit account");
+    }
+    save_data(service);
+    return render_simple_page(conn, service, "account.html", "credit account created",
+                              username);
+}
+
+Result<void> handle_deposit(Connection& conn, BankService& service,
+                            const QueryFields& form) {
+    std::string username = field(form, "username");
+    double amount = 0;
+    if (username.empty() || field(form, "account_id").empty() ||
+        !parse_double(form, "amount", amount)) {
+        return render_error(conn, HttpStatus::BadRequest,
+                            "username, account_id, and amount are required");
+    }
+    if (!service.deposit(username, field(form, "account_id"), amount,
+                         field(form, "desc"))) {
+        return render_error(conn, HttpStatus::BadRequest, "deposit failed");
+    }
+    save_data(service);
+    return render_simple_page(conn, service, "deposit.html", "deposit recorded",
+                              username);
+}
+
+Result<void> handle_withdraw(Connection& conn, BankService& service,
+                             const QueryFields& form) {
+    std::string username = field(form, "username");
+    double amount = 0;
+    if (username.empty() || field(form, "account_id").empty() ||
+        !parse_double(form, "amount", amount)) {
+        return render_error(conn, HttpStatus::BadRequest,
+                            "username, account_id, and amount are required");
+    }
+    if (!service.withdraw(username, field(form, "account_id"), amount,
+                          field(form, "desc"))) {
+        return render_error(conn, HttpStatus::BadRequest, "withdraw failed");
+    }
+    save_data(service);
+    return render_simple_page(conn, service, "withdraw.html", "withdraw recorded",
+                              username);
+}
+
+Result<void> handle_query(Connection& conn, BankService& service,
+                          const QueryFields& fields) {
+    std::string username = field(fields, "username");
+    Replacements replacements = base_replacements(service, "", username);
+    int year = 0;
+    int month = 0;
+    if (!username.empty() && parse_int(fields, "year", year) &&
+        parse_int(fields, "month", month)) {
+        BankService::TransactionSort sort =
+            field(fields, "sort") == "amount_desc"
+                ? BankService::TransactionSort::AmountDescending
+                : BankService::TransactionSort::TimeAscending;
+        replacements.push_back({"{{message}}", "query complete"});
+        replacements.push_back({"{{transactions}}",
+                                format_transactions(service.queryMonthlyTransactions(
+                                    username, year, month, sort))});
+    }
+    return write_template(conn, HttpStatus::OK, "query.html", replacements);
+}
+
+Result<void> handle_stats(Connection& conn, BankService& service,
+                          const QueryFields& fields) {
+    std::string username = field(fields, "username");
+    Replacements replacements = base_replacements(service, "", username);
+    int year = 0;
+    int month = 0;
+    if (!username.empty() && parse_int(fields, "year", year) &&
+        parse_int(fields, "month", month)) {
+        BankService::MonthlyStats stats =
+            service.getMonthlyStats(username, year, month);
+        replacements.push_back({"{{message}}", "statistics calculated"});
+        replacements.push_back({"{{income}}", std::to_string(stats.income)});
+        replacements.push_back({"{{expense}}", std::to_string(stats.expense)});
+    }
+    return write_template(conn, HttpStatus::OK, "stats.html", replacements);
+}
+
+Result<void> handle_reminders(Connection& conn, BankService& service,
+                              const QueryFields& fields) {
+    std::string username = field(fields, "username");
+    Replacements replacements = base_replacements(service, "", username);
+    if (!username.empty()) {
+        replacements.push_back({"{{message}}", "reminders loaded"});
+        replacements.push_back({"{{reminders}}",
+                                format_reminders(service.getReminders(username))});
+    }
+    return write_template(conn, HttpStatus::OK, "reminders.html", replacements);
+}
+
+Result<void> handle_get(Connection& conn, std::string_view path,
+                        std::string_view query, BankService& service) {
+    QueryFields fields = parse_query(query);
+    std::string username = field(fields, "username");
+
+    if (path == "/") {
+        return render_home(conn, service, "", username);
+    }
+    if (path == "/login") {
+        return render_simple_page(conn, service, "login.html", "", username);
+    }
+    if (path == "/register") {
+        return render_simple_page(conn, service, "register.html", "", username);
+    }
+    if (path == "/account") {
+        return render_simple_page(conn, service, "account.html", "", username);
+    }
+    if (path == "/deposit") {
+        return render_simple_page(conn, service, "deposit.html", "", username);
+    }
+    if (path == "/withdraw") {
+        return render_simple_page(conn, service, "withdraw.html", "", username);
+    }
+    if (path == "/query") {
+        return handle_query(conn, service, fields);
+    }
+    if (path == "/stats") {
+        return handle_stats(conn, service, fields);
+    }
+    if (path == "/reminders") {
+        return handle_reminders(conn, service, fields);
+    }
+    if (path == "/error") {
+        return render_error(conn, HttpStatus::OK, "error");
+    }
+    return render_error(conn, HttpStatus::NotFound, "page not found");
+}
+
+Result<void> handle_post(Connection& conn, std::string_view path,
+                         std::string_view body, BankService& service) {
+    QueryFields form = parse_query(body);
+    if (path == "/login") {
+        return handle_login(conn, service, form);
+    }
+    if (path == "/register") {
+        return handle_register(conn, service, form);
+    }
+    if (path == "/account/savings") {
+        return handle_savings(conn, service, form);
+    }
+    if (path == "/account/credit") {
+        return handle_credit(conn, service, form);
+    }
+    if (path == "/deposit") {
+        return handle_deposit(conn, service, form);
+    }
+    if (path == "/withdraw") {
+        return handle_withdraw(conn, service, form);
+    }
+    return render_error(conn, HttpStatus::MethodNotAllowed, "method not allowed");
+}
+
+Result<void> handle_request(Connection conn, BankService& service,
+                            std::mutex& service_mutex,
+                            const AppConfig& config) {
+    auto req_res = read_http_request(conn, config.http_config);
+    if (!req_res) {
+        return render_error(conn, HttpStatus::BadRequest, "bad request");
+    }
+
+    const HttpRequest& request = req_res.value();
+    try {
+        std::lock_guard<std::mutex> lock(service_mutex);
+        if (request.method == HttpMethod::GET) {
+            return handle_get(conn, request.path, request.query, service);
+        }
+        if (request.method == HttpMethod::POST) {
+            return handle_post(conn, request.path, request.body, service);
+        }
+        return render_error(conn, HttpStatus::MethodNotAllowed,
+                            "method not allowed");
+    } catch (const std::exception& ex) {
+        return render_error(conn, HttpStatus::InternalServerError, ex.what());
+    }
+}
+}  // namespace
+
+int main() {
+    AppConfig config = DEFAULT_CONFIG;
+    BankService service;
+    std::mutex service_mutex;
+
+    try {
+        load_existing_data(service);
+    } catch (const std::exception& ex) {
+        std::cerr << "data load skipped: " << ex.what() << '\n';
+    }
+
+    Server server(config.net_config);
+    auto start_res = server.start();
+    if (!start_res) {
+        std::cerr << "server start failed\n";
+        return 1;
+    }
+
+    std::cout << "listening on http://localhost:" << config.net_config.port << '\n';
+    std::cout << "try: http://localhost:" << config.net_config.port << "/\n";
+
+    auto run_res = server.run([&](Connection conn) {
+        return handle_request(std::move(conn), service, service_mutex, config);
+    });
+    if (!run_res) {
+        std::cerr << "server run failed\n";
+        return 1;
+    }
+    return 0;
+}
