+        User* user = findUser(username);
+        if (user == nullptr || accountId.empty() ||
+            findAccountState(username, accountId) != nullptr) {
+            throw std::runtime_error("invalid account file");
+        }
+
+        AccountType type = accountTypeFromCode(typeCode);
+        Date accDate(accYear, accMonth, accDay);
+        std::unique_ptr<Account> account;
+        if (type == AccountType::Savings) {
+            if (balance < 0 || credit != 0 || fee != 0) {
+                throw std::runtime_error("invalid account file");
+            }
+            account = std::make_unique<SavingsAccount>(accDate, accountId, rate);
+        } else {
+            if (credit < 0 || fee < 0 || balance + credit < 0) {
+                throw std::runtime_error("invalid account file");
+            }
+            account =
+                std::make_unique<CreditAccount>(accDate, accountId, credit, rate,
+                                                fee);
+        }
+
+        AccountState state;
+        state.account = user->addAccount(std::move(account));
